pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound inputs to realistic ranges to avoid overflow/underflow
        vm.assume(depositAmount > 0 && depositAmount <= 1e27);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // Record initial balance of msg.sender (this contract)
        uint256 initialBalance = address(this).balance;

        // Give this contract sufficient ETH
        vm.deal(address(this), depositAmount + 1 ether);

        // Deposit the amount
        (bool successDeposit, ) = address(c).call{value: depositAmount}(abi.encodeWithSignature("deposit()"));
        require(successDeposit, "deposit failed");

        // Withdraw the amount (or any amount <= deposited)
        (bool successWithdraw, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", withdrawAmount));
        require(successWithdraw, "withdraw failed");

        // The general rule: after deposit + withdraw, the caller's ETH balance should be
        // initialBalance + depositAmount - withdrawAmount (since withdraw should send the requested amount)
        // This holds for reference C but fails for buggy M (which sends 0)
        uint256 expectedBalance = initialBalance + depositAmount - withdrawAmount;
        assertTrue(address(this).balance == expectedBalance, "Balance invariant violated");
    }
}

