import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1e18);
        vm.assume(withdrawAmount <= depositAmount);
        vm.assume(address(c).balance + depositAmount <= address(this).balance);

        uint256 before = address(this).balance;
        c.deposit{value: depositAmount}();
        c.withdraw(withdrawAmount);
        uint256 after = address(this).balance;
        // Reference: withdraw sends amount to caller, so net change = deposit - withdraw
        // Bug: withdraw sends 0, so net change = deposit
        assertTrue(after - before == depositAmount - withdrawAmount);
    }
}

