pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound depositAmount to prevent overflow in deposit (assert ensures no overflow, but bound to avoid revert)
        vm.assume(depositAmount > 0 && depositAmount < type(uint256).max / 2);
        // Bound withdrawAmount to be small to ensure possible valid calls
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);
        // Give user enough ETH
        vm.deal(user, depositAmount + 1 ether);
        // Perform a deposit from user
        vm.prank(user);
        c.deposit{value: depositAmount}();
        // Optionally withdraw some (may revert if amount > balance, but we bound it, so it will succeed)
        vm.prank(user);
        c.withdraw(withdrawAmount);
        // Now compute sum of balances via the public getter
        uint256 sumBalances = c.balances(user);
        // After withdraw, if withdrawAmount <= depositAmount, the balance should be depositAmount - withdrawAmount
        // Contract's balance should be depositAmount - withdrawAmount (since funds are transferred out)
        // The rule: sumBalances == address(c).balance (since creator didn't deposit anything)
        assertTrue(sumBalances == address(c).balance);
    }
}

